class DynamicArray {
    int* data;
    size_t len;
public:
    // Ctor (Rule of Three applies because of 'new')
    DynamicArray(size_t l) : len(l), data(new int[l]) {}

    // 1. Destructor: MUST clean up dynamic resource
    ~DynamicArray() { delete[] data; }

    // 2. Copy Constructor: MUST perform deep copy
    DynamicArray(const DynamicArray& other)
        : len(other.len), data(new int[other.len]) {
        for (size_t i = 0; i < len; ++i) data[i] = other.data[i];
    }

    // 3. Copy Assignment Operator: Handle self-assignment, cleanup, deep copy
    DynamicArray& operator=(const DynamicArray& other) {
        if (this != &other) {
            delete[] data;
            len = other.len;
            data = new int[len];
            for (size_t i = 0; i < len; ++i) data[i] = other.data[i];
        }
        return *this;
    }
};
